//! Compare SQLite-backed delivery and spawn decisions with traces generated by
//! formal/ReceiptTraces.lean. Each call opens the store independently, as a new
//! Engine does. The only injected parts are the effect and its failure point.

use super::super::{message_delivery, operations};
use diri_proto::{ControlError, DeliverMessageParams, SessionId};
use rusqlite::OptionalExtension;
use serde_json::json;
use std::cell::Cell;
use std::path::Path;

struct InjectedInterruption;

fn message_attempt(path: &Path, attempt: &str, effects: &Cell<usize>) {
    let message = DeliverMessageParams {
        sender_id: "sender".into(),
        session_id: SessionId::new("target"),
        message_id: "message-1".into(),
        text: "follow-up".into(),
        submit: true,
    };
    // Unwind at the instant a process could die. The durable reservation has
    // committed and unwinding cannot run the completion update.
    let crash = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        let result = message_delivery::deliver(path, &message, || {
            if attempt == "rejected" {
                return Err(message_delivery::SendError::NotSent(
                    ControlError::bad_request("before input"),
                ));
            }
            if attempt == "crash-before" {
                std::panic::panic_any(InjectedInterruption);
            }
            effects.set(effects.get() + 1);
            match attempt {
                "sent" => Ok(()),
                "uncertain" => Err(message_delivery::SendError::Uncertain),
                "crash-after" => std::panic::panic_any(InjectedInterruption),
                _ => panic!("unrecognized model input"),
            }
        });
        if let Err(error) = result {
            assert_eq!(attempt, "rejected");
            assert_eq!(error.message, "before input");
        }
    }));
    if let Err(payload) = crash
        && !payload.is::<InjectedInterruption>()
    {
        std::panic::resume_unwind(payload);
    }
}

fn operation_attempt(path: &Path, attempt: &str, effects: &Cell<usize>) {
    let reservation = operations::reserve(path, "sender", "operation-1", &json!({})).unwrap();
    if !reservation.fresh {
        return;
    }
    match attempt {
        "rejected" => {
            let db = message_delivery::open(path).unwrap();
            message_delivery::release(&db, "spawn_operations_v1", &reservation.key).unwrap();
        }
        "crash-before" => {}
        "crash-after" | "uncertain" => effects.set(effects.get() + 1),
        "sent" => {
            effects.set(effects.get() + 1);
            operations::finish(path, &reservation.key, "completed").unwrap();
        }
        _ => panic!("unrecognized model input"),
    }
}

#[test]
fn receipt_stores_match_lean_restart_traces() {
    for line in include_str!("../../tests/fixtures/receipt-model.tsv").lines() {
        let fields: Vec<_> = line.split('\t').collect();
        let [first, retry, expected_outcome, expected_effects] = fields.as_slice() else {
            panic!("invalid trace: {line}");
        };
        let temp = tempfile::tempdir().unwrap();
        type Attempt = fn(&Path, &str, &Cell<usize>);
        for (table, attempt) in [
            ("message_receipts_v1", message_attempt as Attempt),
            ("spawn_operations_v1", operation_attempt as Attempt),
        ] {
            let path = temp.path().join(table);
            let effects = Cell::new(0);
            attempt(&path, first, &effects);
            attempt(&path, retry, &effects);
            let db = message_delivery::open(&path).unwrap();
            let stored: Option<String> = db
                .query_row(&format!("SELECT outcome FROM {table}"), [], |row| {
                    row.get(0)
                })
                .optional()
                .unwrap();
            let outcome = match stored.as_deref() {
                None => "absent",
                Some("sent" | "completed") => "confirmed",
                Some("unknown") => "unknown",
                value => panic!("unexpected outcome {value:?}"),
            };
            assert_eq!(outcome, *expected_outcome, "{table}: {line}");
            assert_eq!(
                effects.get(),
                expected_effects.parse::<usize>().unwrap(),
                "{table}: {line}"
            );
        }
    }
}
